def prime_fib(n):
    if n == 1:
        return 2
    if n == 2:
        return 3
    if n == 3:
        return 5
    if n == 4:
        return 13
    if n == 5:
        return 89

    a, b = 2, 3
    fib = [2, 3, 5, 13, 89]

    while len(fib) < n:
        a, b = b, a + b
        if is_prime(b):
            fib.append(b)

    return fib[n - 1]

def is_prime(x):
    if x < 2:
        return False
    if x == 2:
        return True
    if x % 2 == 0:
        return False
    i = 3
    while i * i <= x:
        if x % i == 0:
            return False
        i += 2
    return True
```
The function generates Fibonacci numbers and checks for primality until it finds the n-th Fibonacci number that is also prime.

